<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import StudentShell from '$lib/components/StudentShell.svelte'; import { apiError, requireStudent, type StudentSession } from '$lib/student-session'; let session: StudentSession | null = null; let items: any[] = []; let error = ''; onMount(async () => { session = await requireStudent(); if (!session) return; try { items = await api<any[]>('/api/student/achievements'); } catch (e) { error = apiError(e); } });</script>
{#if session}<StudentShell {session} active="achievements"><section class="student-heading"><span class="student-eyebrow">MILESTONES</span><h1>ACHIEVEMENTS</h1><p>Every earned badge is a record of consistent training.</p></section>{#if error}<div class="error">{error}</div>{:else if items.length === 0}<section class="student-panel empty-panel"><span class="rank-orb">★</span><h2>Your next milestone is ahead.</h2><p>Keep training. Achievements awarded by the dojo will appear here.</p></section>{:else}<div class="achievement-grid">{#each items as item}<article class="achievement-card"><span class="achievement-icon">{item.iconName ?? '★'}</span><div><h2>{item.name}</h2><p>{item.description ?? 'Dojo milestone earned.'}</p><small>{item.awardedAt ? new Date(item.awardedAt).toLocaleDateString() : ''}</small></div></article>{/each}</div>{/if}</StudentShell>{/if}
